"""Consulta pública de reservas."""
from fastapi import APIRouter

from app import db
from app.models import Reserva

router = APIRouter()


@router.get("/reservas")
def listar_reservas() -> list[Reserva]:
    return db.listar_reservas()

"""Validaciones de reservas.

validar_sala() y validar_horario() son independientes entre sí.
"""
from datetime import datetime

from app.config import SALAS


class ValidationError(Exception):
    pass


def validar_sala(sala: str) -> None:
    if not sala:
        raise ValidationError("sala requerida")
    if sala not in SALAS:
        raise ValidationError("sala invalida")


# --- Parámetros de reserva -------------------------------------------------

DURACION_MAXIMA_MIN = 240
MINUTOS_PERMITIDOS = (0, 30)


def _es_duracion_valida(duracion_min: int) -> bool:
    return 0 < duracion_min <= DURACION_MAXIMA_MIN


# ---------------------------------------------------------------------------


def validar_horario(fecha: datetime, duracion_min: int) -> None:
    if not _es_duracion_valida(duracion_min):
        raise ValidationError("duracion invalida")
    if fecha.minute not in MINUTOS_PERMITIDOS or fecha.second or fecha.microsecond:
        raise ValidationError("minutos invalidos")

from fastapi import APIRouter, Depends, Header, HTTPException

from app import db
from app.auth import Session, get_session
from app.models import Reserva, ReservaIn
from app.validators import ValidationError, validar_horario, validar_sala

router = APIRouter()


def sesion_actual(authorization: str | None = Header(default=None)) -> Session:
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="no autenticado")
    session = get_session(authorization.removeprefix("Bearer "))
    if session is None:
        raise HTTPException(status_code=401, detail="sesion invalida")
    return session


@router.post("/reservas", status_code=201)
def crear_reserva(r: ReservaIn, session: Session = Depends(sesion_actual)) -> Reserva:
    try:
        validar_sala(r.sala)
        validar_horario(r.fecha, r.duracion_min)
    except ValidationError as e:
        raise HTTPException(status_code=422, detail=str(e))
    return db.insertar_reserva(r, session.username)

import pytest
from fastapi.testclient import TestClient


@pytest.fixture
def client(tmp_path, monkeypatch):
    monkeypatch.setenv("MEDULA_DB_PATH", str(tmp_path / "test.db"))
    from app.main import app

    with TestClient(app) as c:
        yield c


@pytest.fixture
def token(client):
    r = client.post("/login", json={"username": "alice", "password": "alice-pass"})
    return r.json()["token"]


@pytest.fixture
def auth(token):
    return {"Authorization": f"Bearer {token}"}

RESERVA = {"sala": "Atlas", "inicio": "2026-10-05T10:00", "duracion_min": 60}


def test_crear_y_listar(client, auth):
    r = client.post("/reservas", json=RESERVA, headers=auth)
    assert r.status_code == 201
    creada = r.json()
    assert creada["usuario"] == "alice" and creada["sala"] == "Atlas"
    assert client.get("/reservas").json() == [creada]


def test_listado_ordenado_por_inicio(client, auth):
    client.post("/reservas", json={**RESERVA, "inicio": "2026-10-07T10:00"}, headers=auth)
    client.post("/reservas", json=RESERVA, headers=auth)
    inicios = [r["inicio"] for r in client.get("/reservas").json()]
    assert inicios == sorted(inicios)


def test_crear_sin_sesion(client):
    assert client.post("/reservas", json=RESERVA).status_code == 401
    assert client.post("/reservas", json=RESERVA, headers={"Authorization": "Bearer x"}).status_code == 401


def test_error_de_validacion_devuelve_422(client, auth):
    r = client.post("/reservas", json={**RESERVA, "sala": "Delta"}, headers=auth)
    assert r.status_code == 422
    assert r.json()["detail"]


def test_crear_con_fecha_en_vez_de_inicio_devuelve_422(client, auth):
    payload = {"sala": "Atlas", "fecha": "2026-10-05T10:00", "duracion_min": 60}
    r = client.post("/reservas", json=payload, headers=auth)
    assert r.status_code == 422

